    // 偏差/重规划后，当前状态可能已不满足该步前提 ⇒ 再校验一次（fail-closed）。\r\n    // 即便偏差在容差内（不触发上面的重规划），若后续某步前提已被破坏（如电量跌到不足以执行），\r\n    // 也必须拦下而非盲目执行预规划动作——否则\"证明安全\"会被一个未超容差的偏差悄悄击穿。\r\n    if (cap.pre != null && !applicable(state, cap, step.params)) {\r\n      deviations.push({ step: i, cap: step.cap, type: 'pre-violated', state: Object.assign({}, state) });\r\n      if (typeof EventBus !== 'undefined') EventBus.publish('execution', { type: 'pre-violated', step: i, cap: step.cap });\r\n      if (replans >= maxReplans) { halted = true; haltReason = 'max-replans-exceeded'; break; }\r\n      const rp = planTask(opts.goalFn, opts);\r\n      if (rp.ok) { remaining = rp.plan; i = 0; replans++; continue; }\r\n      halted = true; haltReason = 'no-plan-after-pre-violation'; break;\r\n    }\r\n    let obs = null;\r\n    try { obs = await bodyAdapter(step.cap, step.params); } catch (e) { obs = { ok: false, error: 'body-error:' + e.message }; }\r\n    if (!obs || obs.ok === false) {\r\n      deviations.push({ step: i, cap: step.cap, type: 'execution-failure', error: (obs && obs.error) || 'unknown' });\r\n      // 自动记录失败样本（无需调用方手动 sl_record）：以节点名记录\"从→到\"转移，供 learnedEdgePenalty 学回避\r\n      if (typeof SelfLearn !== 'undefined' && SelfLearn.record) SelfLearn.record({\r\n        state: (plan[i] && plan[i].state != null) ? plan[i].state : (typeof _skey === 'function' ? _skey(state) : state),\r\n        action: step.cap, result: (plan[i] && plan[i].result != null) ? plan[i].result : 'FAIL',\r\n        success: false, reward: -1, env: { step: i, error: (obs && obs.error) || 'unknown', source: 'execute()' }\r\n      });\r\n      if (typeof EventBus !== 'undefined') EventBus.publish('execution', { type: 'failure', step: i, cap: step.cap });\r\n      if (replans >= maxReplans) { halted = true; haltReason = 'max-replans-exceeded'; break; }\r\n      const rp = planTask(opts.goalFn, opts);\r\n      if (rp.ok) { remaining = rp.plan; i = 0; replans++; continue; }\r\n      halted = true; haltReason = 'unrecoverable:' + ((obs && obs.error) || ''); break;\r\n    }\r\n    const observed = Object.assign({}, state, obs.state || {});\r\n    const diff = stateDiff(step.expect, observed);\r\n    if (Object.keys(diff).length) {\r\n      deviations.push({ step: i, cap: step.cap, type: 'state-deviation', diff: diff });\r\n      if (typeof EventBus !== 'undefined') EventBus.publish('execution', { type: 'deviation', step: i, diff: diff });\r\n      const tol = (opts.deviationTolerance == null) ? 1 : opts.deviationTolerance;\r\n      if (Object.keys(diff).length > tol) {\r\n        if (replans >= maxReplans) { halted = true; haltReason = 'max-replans-exceeded'; break; }\r\n        setState(observed);\r\n        const rp = planTask(opts.goalFn, opts);\r\n        if (rp.ok) { remaining = rp.plan; i = 0; replans++; continue; }\r\n        halted = true; haltReason = 'no-plan-after-deviation'; break;\r\n      }\r\n    }\r\n    setState(observed);\r\n    trace.push({ i: i, cap: step.cap, params: step.params, predicted: step.expect, observed: observed, deviation: diff });\r\n    // 自动记录成功样本（含是否出现状态偏差 → 负反馈信号）：以节点名记录\"从→到\"转移\r\n    if (typeof SelfLearn !== 'undefined' && SelfLearn.record) SelfLearn.record({\r\n      state: (plan[i] && plan[i].state != null) ? plan[i].state : (typeof _skey === 'function' ? _skey(state) : state),\r\n      action: step.cap, result: (plan[i] && plan[i].result != null) ? plan[i].result : (typeof _skey === 'function' ? _skey(observed) : observed),\r\n      success: Object.keys(diff).length === 0, reward: Object.keys(diff).length === 0 ? 1 : 0.5,\r\n      env: { step: i, deviation: Object.keys(diff).length, source: 'execute()' }\r\n    });\r\n    i++;\r\n  }\r\n  // 具身对外动作末道防火墙：真实世界执行前，禁止任何 PERCEPTION 感知步骤渗入计划(防幻觉污染物理执行，铁律③)。\r\n  if (plan && Array.isArray(plan)) {\r\n    for (const st of plan) {\r\n      if (st && (st.perceived === true || st.mayHallucinate === true || (st.grounding && st.grounding.tier === 'UNVERIFIED_LLM'))) {\r\n        throw new Error(FIREWALL.REJECTED + ': 对外执行计划含 PERCEPTION 感知步骤 @ execute（须过 liftToBelief 提升为信念）');\r\n      }\r\n    }\r\n  }\r\n  const _ex = { ok: !halted, halted: halted, haltReason: haltReason, steps: trace.length, replans: replans, deviations: deviations, trace: trace, finalState: getState(), goalSatisfied: opts.goalFn ? !!opts.goalFn(getState()) : null, grounding: GROUNDING.KERNEL, disclaimer: '确定化重规划(determinized replanning)：具身标准工程近似，非 POMDP 最优' };\r\n  // 自动记录整段任务（episode）结果：真实世界反馈进入经验库，供 sl_discover 归纳\r\n  if (typeof SelfLearn !== 'undefined' && SelfLearn.record) SelfLearn.record({\r\n    state: 'episode-start', action: 'episode', result: _ex.ok ? 'SUCCESS' : ('FAIL:' + (haltReason || 'unknown')),\r\n    success: _ex.ok, reward: _ex.ok ? 1 : -1,\r\n    env: { replans: replans, deviations: deviations.length, steps: trace.length, source: 'execute()' }\r\n  });\r\n  // 学习回流②：把本次成功的任务路径写入最优路径历史，供 heuristicEvolve 反向传播（越用越准，仍最优）\r\n  if (typeof PLAN_HISTORY !== 'undefined' && plan && plan.length){\r\n    const path = [plan[0].state].concat(plan.map(step => step.result));\r\n    recordPlanHistory(path, opts.goal, _ex.ok);\r\n  }\r\n  LAST_EXECUTION = _ex;\r\n  return _ex;\r\n}\r\nasync function doWork(goalFn, bodyAdapter, opts) {\r\n  const p = planTask(goalFn, opts);\r\n  if (!p.ok) return { ok: false, stage: 'plan', error: p.error, grounding: GROUNDING.KERNEL };\r\n  const ex = await execute(p.plan, bodyAdapter, Object.assign({}, opts, { goalFn: goalFn }));\r\n  return { ok: ex.ok, stage: 'execute', plan: p, execution: ex, grounding: GROUNDING.KERNEL };\r\n}\r\n\r\n// ════════════════════════════════════════════════════════════════════════\r\n// 八元组 𝔹 = (X, h, b, f, U, V, Inv, M) — 世界通用大脑的数学形态（2026-08-31 落地）\r\n// 来源：docs/TUPLE-REEXAMINATION.md 不可约性推导。此前 X/b/f/Inv 隐式存在，\r\n// h/U/V/M 缺位（设计提案未落地）；本次正式建模为可运行、可审计的数学对象。\r\n// 原则：数学层 / 工程层分离 —— 不推翻现有七元组工程，八元组是\"形态学\"叠加层。\r\n// ════════════════════════════════════════════════════════════════════════\r\nconst BrainTuple = {\r\n  // —— X 状态空间：抽象世界节点 ⊕ 物理身体连续状态分量 ——\r\n  X() {\r\n    const world = (getWorld() && getWorld().nodes) ? getWorld().nodes.slice() : [];\r\n    const body = (typeof getState === 'function') ? Object.keys(getState()) : [];\r\n    return { ok: true, world: world, body: body, cardinality: world.length + body.length,\r\n      note: 'X = 抽象世界状态（图节点）⊕ 物理身体连续状态分量' };\r\n  },\r\n  // —— h 观测通道 h: X → O，O 由身体传感器张成（此前仅散落 distinguishable）——\r\n  h(state) {\r\n    if (!getBody() || !getBody().observation || !getBody().observation.sensors) return { ok: false, reason: '未声明观测契约 O（诚实退化，非硬报错）' };\r\n    const O = {};\r\n    for (const name in getBody().observation.sensors) {\r\n      const sp = getBody().observation.sensors[name];\r\n      const f = (sp && sp.field) || name;\r\n      O[name] = (state && state[f] !== undefined) ? state[f] : null;\r\n    }\r\n    return { ok: true, O: O, sensorCount: Object.keys(O).length };\r\n  },\r\n  // —— f 动力学 f: X × U → X（混合：离散图边 ⊕ 具身连续 ⊕ 学习的 f）——\r\n  // 分级诚实（呼应前沿：闭环效用 > 视觉保真；开放世界 f 大多未知，须补学习的 f 但诚实分层）：\r\n  //   · graph-edge / 具身预测 → KERNEL（确定性、可复现）\r\n  //   · 学习的 f（learnWorldModel 拟合）→ PERCEPTION（mayHallucinate，禁止进入 KERNEL/PROOF 证明链）\r\n  //   · 二者皆无 → 诚实返回 𝕌（不编造动力学）\r\n  _learned: null, // 学习的 f（线性 SEM 等），由 setLearnedDynamics 注入\r\n  setLearnedDynamics(model) {\r\n    if (!model || model.error) return { ok: false, reason: '模型无效（learningWorldModel 失败或为空）' };\r\n    this._learned = model;\r\n    return { ok: true, method: model.method, note: '学习的 f 已注入；产物标记为 PERCEPTION（mayHallucinate），不得进入 KERNEL/PROOF 证明链' };\r\n  },\r\n  f(state, action, opts) {\r\n    opts = opts || {};\r\n    if (getWorld() && getWorld().edges) {\r\n      const e = getWorld().edges.find(function (ed) { return ed.from === state && ed.to === action; });\r\n      if (e) return { ok: true, next: action, kind: 'graph-edge', grounding: GROUNDING.KERNEL, mayHallucinate: false,\r\n        cost: (typeof edgeCost === 'function' ? edgeCost(state, action) : 1) };\r\n    }\r\n    // 学习的 f：尽力而为预测，但诚实降级为 PERCEPTION（不进证明链）\r\n    if (this._learned && typeof state === 'object' && typeof simulate === 'function') {\r\n      const sim = simulate(this._learned, (state && typeof state === 'object' ? state : {}), (action && typeof action === 'object' ? action : {}));\r\n      if (sim && sim.next) return { ok: true, next: null, predicted: sim.next, kind: 'learned', grounding: GROUNDING.PERCEPTION,\r\n        mayHallucinate: true, usableInProof: false,\r\n        honesty: '学习的 f 由观测数据拟合（线性 SEM lite），属 PERCEPTION 级：可能幻觉，仅用于探索/规划启发，禁止作为任何证明链前提（铁律③）',\r\n        U: null };\r\n    }\r\n    return { ok: true, next: null, kind: 'unknown', grounding: GROUNDING.KERNEL,\r\n      U: '转移未建模（诚实返回 𝕌，不编造动力学）' };\r\n  },\r\n  // —— f.candidates：非确定转移关系 f ⊆ X×U×X（开放世界核心）——\r\n  // 第一性原理：世界模型是**非确定**的——同态同动作可有多个结局（扰动/他者/未知）。\r\n  // 把 f 从\"单点函数\"升级为\"候选集\"：KERNEL 候选确定，PERCEPTION 候选明确标 nondeterministic，\r\n  // 供 V_robust（区间 MDP 稳健可达）与 execute(useImprecise) 端到端消费不确定性。\r\n  candidates(state, action, opts) {\r\n    opts = opts || {};\r\n    const items = [];\r\n    if (getWorld() && getWorld().edges) {\r\n      const e = getWorld().edges.find(function (ed) { return ed.from === state && ed.to === action; });\r\n      if (e) items.push({ next: action, kind: 'graph-edge', grounding: GROUNDING.KERNEL, mayHallucinate: false, weight: 1 });\r\n    }\r\n    if (this._learned && typeof state === 'object' && typeof simulate === 'function') {\r\n      const sim = simulate(this._learned, (state && typeof state === 'object' ? state : {}), (action && typeof action === 'object' ? action : {}));\r\n      if (sim && sim.next != null) items.push({ next: sim.next, kind: 'learned', grounding: GROUNDING.PERCEPTION, mayHallucinate: true, usableInProof: false, weight: 1,\r\n        honesty: '学习的 f 由观测拟合（线性 SEM lite），属 PERCEPTION：可能幻觉，仅探索/规划启发，不进证明链' });\r\n    }\r\n    const nondeterministic = items.length === 0 || items.some(function (it) { return it.grounding !== GROUNDING.KERNEL; });\r\n    return { ok: true, from: state, via: action, items: items, nondeterministic: nondeterministic,\r\n      note: items.length ? '非确定转移关系：返回候选集；KERNEL 候选确定参与悲观可达，PERCEPTION 候选仅乐观侧、须保守'\r\n                          : '无候选（诚实返回空集，转移未建模 𝕌）' };\r\n  },\r\n  // —— U 执行通道 U ⊆ actions：当前安全可执行动作集（checkHard 双层 + IRREVERSIBLE 授权后）——\r\n  U(opts) {\r\n    opts = opts || {};\r\n    const caps = (getBody() && getBody().caps) ? getBody().caps : [];\r\n    const safe = [];\r\n    for (const id of caps) {\r\n      const step = { cap: id, params: {} };\r\n      const chk = (typeof checkHard === 'function') ? checkHard((typeof getState === 'function' ? getState() : {}), step) : { ok: true };\r\n      if (chk.ok) {\r\n        const cap = (typeof CAPS !== 'undefined') ? CAPS[id] : null;\r\n        if (cap && cap.irreversible === true && !opts.allowIrreversible) continue; // IRREVERSIBLE-HALT\r\n        safe.push(id);\r\n      }\r\n    }\r\n    return { ok: true, actions: safe, total: caps.length, blocked: caps.length - safe.length,\r\n      note: 'U = getBody().caps 经 checkHard 双层 + IRREVERSIBLE-HALT 后剩余的安全可执行集' };\r\n  },\r\n  // —— V 价值 V: X → [0,1]：到达价值，值迭代固定点（复用 ima_291 目标导向框架）——\r\n  V(goal, opts) {\r\n    if (!getWorld() || !getWorld().nodes || !getWorld().nodes.length) return { ok: false, reason: '无世界图，价值未定义' };\r\n    const goalNode = (typeof goal === 'string') ? goal : null;\r\n    const goalFn = (typeof goal === 'function') ? goal : null;\r\n    const V = {};\r\n    getWorld().nodes.forEach(function (s) { V[s] = (goalNode ? (s === goalNode ? 1 : 0) : (goalFn && goalFn(s) ? 1 : 0)); });\r\n    const adj = {}; getWorld().nodes.forEach(function (s) { adj[s] = []; });\r\n    (getWorld().edges || []).forEach(function (e) { if (adj[e.from]) adj[e.from].push(e.to); });\r\n    for (let it = 0; it < getWorld().nodes.length + 2; it++) {\r\n      for (const s of getWorld().nodes) {\r\n        if ((goalNode && s === goalNode) || (goalFn && goalFn(s))) continue;\r\n        const ch = adj[s]; if (!ch.length) continue;\r\n        let best = 0; for (const nx of ch) best = Math.max(best, V[nx]); V[s] = best;\r\n      }\r\n    }\r\n    const startKey = (typeof getState === 'function' && getState() && typeof _skey === 'function') ? _skey(getState()) : (getWorld().nodes[0]);\r\n    return { ok: true, V: V, startValue: (V[startKey] !== undefined ? V[startKey] : 0), goal: goal,\r\n      note: 'V: X→[0,1] 到达价值（值迭代固定点，≤|X| 步收敛）' };\r\n  },\r\n  // —— V_robust：区间 MDP 稳健可达性（悲观/乐观包络）[P0 端到端主线] ——\r\n  // 第一性原理（稳健/分布鲁棒 MDP）：安全关键大脑不应给\"脆\"的必达性。同一态在**最坏不确定**下可达 vs\r\n  // **最好不确定**下可达，构成 [V_low, V_high] 包络：\r\n  //   (1,1) 稳健可达 ⇒ 即使最坏不确定也达目标； (0,1) 风险可达 ⇒ 仅赖可能幻觉的 PERCEPTION 转移，须保守/人机协同； (0,0) 不可达。\r\n  // 悲观=仅 KERNEL 图边推进；乐观=图边+学习的f预测（PERCEPTION 仅乐观侧）。两次值迭代皆压缩映射（THM_BANACH_FP）。\r\n  V_robust(goal, opts) {\r\n    if (!getWorld() || !getWorld().nodes || !getWorld().nodes.length) return { ok: false, reason: '无世界图，价值未定义' };\r\n    const goalNode = (typeof goal === 'string') ? goal : null;\r\n    const goalFn = (typeof goal === 'function') ? goal : null;\r\n    const isGoal = function (s) { return (goalNode && s === goalNode) || (goalFn && goalFn(s)); };\r\n    const nodes = getWorld().nodes;\r\n    const adjOpt = {}, adjPes = {};\r\n    nodes.forEach(function (s) { adjOpt[s] = []; adjPes[s] = []; });\r\n    (getWorld().edges || []).forEach(function (e) { if (adjOpt[e.from]) { adjOpt[e.from].push(e.to); adjPes[e.from].push(e.to); } });\r\n    // 学习的 f 预测作为乐观可达边（仅乐观侧；PERCEPTION 不进悲观侧）\r\n    if (this._learned) {\r\n      for (const s of nodes) for (const a of nodes) {\r\n        const cand = this.f.candidates(s, a);\r\n        if (cand && cand.items) for (const it of cand.items) if (it.kind === 'learned' && it.next != null) adjOpt[s].push(it.next);\r\n      }\r\n    }\r\n    const reach = function (adj) {\r\n      const Vr = {}; nodes.forEach(function (s) { Vr[s] = isGoal(s) ? 1 : 0; });\r\n      for (let it = 0; it < nodes.length + 2; it++)\r\n        for (const s of nodes) { if (isGoal(s)) continue; const ch = adj[s]; if (!ch.length) continue; let best = 0; for (const nx of ch) best = Math.max(best, Vr[nx]); Vr[s] = best; }\r\n      return Vr;\r\n    };\r\n    const Vopt = reach(adjOpt), Vpes = reach(adjPes);\r\n    const env = {}; nodes.forEach(function (s) { env[s] = { low: Vpes[s], high: Vopt[s] }; });\r\n    const classify = function (s) { if (Vpes[s] >= 1 && Vopt[s] >= 1) return 'robust'; if (Vopt[s] >= 1) return 'risky'; return 'unreachable'; };\r\n    const startKey = (typeof getState === 'function' && getState() && typeof _skey === 'function') ? _skey(getState()) : nodes[0];\r\n    // 当前物理态不在世界图节点内（仅身体态，未对齐到图节点）时，不返回 null（裸 null 不诚实），\r\n    // 改为对整图做稳健可达态势聚合：任一节点 robust ⇒ 全局 robust；有可达但无 robust ⇒ risky；全不可达 ⇒ unreachable。\r\n    let aggregate = null;\r\n    if (!env[startKey]) {\r\n      let hasRobust = false, hasReach = false;\r\n      for (const s of nodes) { const c = classify(s); if (c === 'robust') hasRobust = true; if (c !== 'unreachable') hasReach = true; }\r\n      aggregate = hasReach ? (hasRobust ? 'robust' : 'risky') : 'unreachable';\r\n    }\r\n    return { ok: true, V_low: Vpes, V_high: Vopt, envelope: env,\r\n      classification: env[startKey] ? classify(startKey) : aggregate,\r\n      startKey: env[startKey] ? startKey : null,\r\n      method: '区间 MDP 稳健可达性（悲观仅 KERNEL 图边 / 乐观含 PERCEPTION 学习f 预测）',\r\n      note: '稳健可达(1,1) ⇒ 最坏不确定也达目标；风险可达(0,1) ⇒ 仅赖可能幻觉的转移，须保守/人机协同；不可达(0,0)' };\r\n  },\r\n  // —— adversarialValue：零和极小极大对抗可达性 [G1 多智能体对抗层] ——\r\n  // 第一性原理（minimax / 博弈论）：真实世界有其他会\"使坏\"的智能体。大脑不应只算自己最优，\r\n  // 而应算\"对手最优破坏下我仍能保证的到达度\"。有界视野双人递归：智能体最大化、对手最小化，终值取 V_robust 悲观 low\r\n  // （对手不借 PERCEPTION 幻觉转移得利）。复用 THM_MINIMAX_ADVERSARIAL。\r\n  adversarialValue(goal, opts) {\r\n    opts = opts || {};\r\n    if (!getWorld() || !getWorld().nodes || !getWorld().nodes.length) return { ok: false, reason: '无世界图，对抗价值未定义' };\r\n    const horizon = Math.max(1, Math.min(opts.horizon || 1, 3));\r\n    const self = this;\r\n    const goalNode = (typeof goal === 'string') ? goal : null;\r\n    const goalFn = (typeof goal === 'function') ? goal : null;\r\n    const isGoal = function (s) { return (goalNode && s === goalNode) || (goalFn && goalFn(s)); };\r\n    const outs = {}; (getWorld().edges || []).forEach(function (e) { if (!outs[e.from]) outs[e.from] = []; outs[e.from].push(e.to); });\r\n    const term = function (s) { const r = self.V_robust(goal, { startKey: s }); const v = (r.ok && r.envelope[s]) ? r.envelope[s].low : 0; return v; };\r\n    const memo = {};\r\n    function rec(s, h, agentTurn) {\r\n      if (isGoal(s)) return 1;\r\n      if (h <= 0) return term(s);\r\n      const key = s + '#' + h + '#' + (agentTurn ? 1 : 0); if (memo[key] != null) return memo[key];\r\n      const next = outs[s] || [];\r\n      if (!next.length) return memo[key] = term(s);\r\n      let val;\r\n      if (agentTurn) { let best = 0; for (const nx of next) best = Math.max(best, rec(nx, h - 1, false)); val = best; }\r\n      else { let worst = 1; for (const nx of next) worst = Math.min(worst, rec(nx, h - 1, true)); val = worst; }\r\n      return memo[key] = val;\r\n    }\r\n    const startKey = (typeof getState === 'function' && getState() && typeof _skey === 'function') ? _skey(getState()) : getWorld().nodes[0];\r\n    const value = rec(startKey, horizon, true);\r\n    const classify = function (v) { return v >= 1 ? 'robust' : (v > 0 ? 'risky' : 'unreachable'); };\r\n    return { ok: true, value: +value.toFixed(4), classification: classify(value), horizon: horizon,\r\n      method: '零和极小极大可达性（智能体最大化最坏情形 / 对手最小化可达性，有界视野复用 V_robust 终值）',\r\n      note: '价值=对手最优破坏下仍能保证的到达度；robust(1)抗最坏对手仍达，risky(0,1)须保守/人机协同，unreachable(0)' };\r\n  },\r\n  // —— physicsInvariant：物理正确性第二层（守恒律/Noether）[P0 另补的\"别的数学思想\"] ——\r\n  // 量纲只挡单位错；守恒律挡物理定律错。给定 flow/energy 则数值检验 dE/dt≈0；否则诚实 UNKNOWN。\r\n  physicsInvariant(spec, opts) {\r\n    opts = opts || {};\r\n    if (!spec || !spec.flow || !spec.energy) return { ok: false, reason: '未提供 flow/energy，物理守恒不可判定', verdict: 'UNKNOWN' };\r\n    const r = conservationCheck(spec.flow, spec.energy, spec.x0, spec.dt, spec.steps);\r\n    return { ok: true, verdict: r.verdict, maxDriftRate: r.maxDriftRate, U: r.verdict === 'UNKNOWN',\r\n      note: '物理守恒不变量（Noether）：接 Inv() 作为物理正确性第二层（量纲 → 守恒律）' };\r\n  },\r\n  // —— Inv 不变量：硬约束禁集 ∪ 物理安全包线 ∪ 量纲齐备性 ∪ 守恒律（可选）——\r\n  Inv() {\r\n    const hard = ((getBody() && getBody().hard) || []).concat((getWorld() && getWorld().hard) || []);\r\n    const dimOk = (getBody() && getBody().dimensions && typeof checkDimensions === 'function') ? checkDimensions((typeof CAPS !== 'undefined' ? CAPS : {}), getBody().dimensions).ok : null;\r\n    return { ok: true, hardConstraints: hard.length, dimensionSound: dimOk,\r\n      note: 'Inv = 硬约束禁集 ∪ 物理安全包线 ∪ 量纲齐备性（物理正确性第1层）；守恒律见 physicsInvariant（第2层）' };\r\n  },\r\n  // —— M 他心：对其他 agent 的**信念状态**（信念级，非证明级/非读心器）——\r\n  M: {\r\n    agents: {},\r\n    registerAgent(j, belief) {\r\n      if (!j) return { ok: false, reason: 'agent id 必填' };\r\n      this.agents[j] = { belief: (belief || null), observations: [], registeredAt: Date.now() };\r\n      return { ok: true, agent: j, count: Object.keys(this.agents).length };\r\n    },\r\n    observeAgent(j, obs) {\r\n      if (!this.agents[j]) this.registerAgent(j, null);\r\n      this.agents[j].observations.push(obs);\r\n      return { ok: true, agent: j, observations: this.agents[j].observations.length };\r\n    },\r\n    beliefAbout(j) {\r\n      const a = this.agents[j];\r\n      if (!a) return { ok: false, reason: '未登记他心 agent: ' + j };\r\n      return { ok: true, agent: j, belief: a.belief, observations: a.observations.length,\r\n        honesty: 'BELIEF-LEVEL: 他心真实性不可判定（中文房间/他心问题），本结构仅建模我方对其的信念，不声称读取真实心智' };\r\n    },\r\n    // 可被伪装性：在观测契约 O 下，他心 j 的真实态与伪装态是否可区分 ⟹ 评估 deception bound\r\n    deceptionBound(j, trueState, maskState) {\r\n      const a = this.agents[j];\r\n      if (!a) return { ok: false, reason: '未登记他心 agent: ' + j };\r\n      if (!getBody() || !getBody().observation) return { ok: false, reason: '未声明观测契约 O，无法评估伪装性' };\r\n      const dist = (typeof distinguishable === 'function') ? distinguishable(trueState, maskState, getBody().observation) : null;\r\n      return { ok: true, agent: j, distinguishable: dist, deceptionPossible: (dist === false),\r\n        honesty: 'BELIEF-LEVEL: 仅评估我方观测下的可区分性，不代表他心真实意图' };\r\n    },\r\n    // —— 嵌套信念（KD45 模态逻辑）：建模\"我信 j 信 k 信 p\" ——\r\n    // 第一性原理（心智理论 + 模态逻辑 KD45）：通用大脑须能推理**他心的他心**（嵌套信念），\r\n    // 否则 ToM 只到一层。每个信念算子 B_a 应满足 KD45：K 分配律 / D 一致性(不矛盾) / 4 正内省 / 5 负内省。\r\n    // 诚实边界：嵌套信念是 BELIEF-LEVEL 建模（我方对他心的信念的他心的信念…），非读取真实心智；不进证明链。\r\n    nested: [],\r\n    assertNested(observer, path, prop, opts) {\r\n      opts = opts || {};\r\n      if (!observer || !Array.isArray(path) || !prop) return { ok: false, reason: 'observer/path[]/prop 必填' };\r\n      const inner = path.reduceRight(function (acc, a) { return 'B_' + a + '(' + acc + ')'; }, String(prop));\r\n      const formula = 'B_' + observer + '(' + inner + ')';\r\n      this.nested.push({ observer: observer, path: path.slice(), prop: String(prop), negated: !!opts.negated,\r\n        formula: formula, grounding: 'BELIEF-LEVEL', source: opts.source || null, at: Date.now() });\r\n      return { ok: true, observer: observer, depth: path.length, formula: formula, grounding: 'BELIEF-LEVEL',\r\n        honesty: 'BELIEF-LEVEL: 嵌套信念为我方对他心的信念建模，不声称读取真实心智；深度越深越不确定' };\r\n    },\r\n    nestedBelief(observer, path, prop, opts) {\r\n      opts = opts || {};\r\n      const wantNeg = !!opts.negated;\r\n      const hit = this.nested.find(function (e) { return e.observer === observer && e.prop === String(prop) &&\r\n        e.path.length === path.length && e.path.every(function (a, i) { return a === path[i]; }) && e.negated === wantNeg; });\r\n      if (!hit) return { ok: true, known: false, belief: null, grounding: 'BELIEF-LEVEL',\r\n        honesty: 'BELIEF-LEVEL: 未存该嵌套信念 ⟹ 诚实返回 UNKNOWN（不编造他心信念）' };\r\n      return { ok: true, known: true, belief: !hit.negated, negated: hit.negated, formula: hit.formula,\r\n        grounding: 'BELIEF-LEVEL', honesty: 'BELIEF-LEVEL: 嵌套信念建模，非真实心智读取' };\r\n    },\r\n    // —— checkKd45：机验观察者信念算子 B_observer 的 D 一致性（KD45 中唯一可操作化硬检查）——\r\n    // K/D/4/5 是信念算子的建模契约；其中 D（不自相矛盾）可逐条扫描硬验证，4/5 内省作为诚实声明的建模假设。\r\n    checkKd45(observer) {\r\n      if (!observer) return { ok: false, reason: 'observer 必填' };\r\n      const groups = {};\r\n      this.nested.forEach(function (e) {\r\n        if (e.observer !== observer) return;\r\n        const k = e.path.join('/') + ':' + e.prop;\r\n        if (!groups[k]) groups[k] = { pos: false, neg: false };\r\n        if (e.negated) groups[k].neg = true; else groups[k].pos = true;\r\n      });\r\n      const violations = [];\r\n      for (const k in groups) if (groups[k].pos && groups[k].neg) violations.push({ formula: k, type: 'D-inconsistency' });\r\n      return { ok: true, observer: observer, consistent: violations.length === 0, violations: violations,\r\n        dCheck: violations.length === 0 ? 'PASS' : 'FAIL',\r\n        axioms: { K: 'assumed-distribution', D: violations.length === 0 ? 'verified' : 'violated', '4': 'assumed-positive-introspection', '5': 'assumed-negative-introspection' },\r\n        grounding: 'BELIEF-LEVEL',\r\n        honesty: 'BELIEF-LEVEL: KD45 是信念算子建模契约；D 一致性已机验，4/5 内省为诚实声明的假设（非机器证明）' };\r\n    }\r\n  },\r\n  // —— B 信念态（第九元扩展）：部分可观测下大脑维持对 X 的信念分布 Δ(X)，非单点估计 ——\r\n  // 诚实标注：信念 = 观测后验（AX_PROB），属 BELIEF-LEVEL / conjecture 级，禁止进入证明链（铁律③）。\r\n  _belief: null,\r\n  B(candidates, opts) {\r\n    opts = opts || {};\r\n    if (candidates && Array.isArray(candidates)) {\r\n      const n = candidates.length; if (!n) return { ok: false, reason: '候选集为空' };\r\n      const w0 = candidates.map(c => (c && typeof c === 'object' && isFinite(c.weight) ? c.weight : 1));\r\n      const sum = w0.reduce((a, b) => a + b, 0) || n;\r\n      const dist = {}; candidates.forEach((c, i) => { const k = (c && c.key) || ('s' + i); dist[k] = +(w0[i] / sum).toFixed(6); });\r\n      this._belief = { dist: dist, obs: [], updatedAt: Date.now(), evidence: 0 };\r\n      return { ok: true, belief: dist, cardinality: n, grounding: GROUNDING.KERNEL,\r\n        note: 'B: Δ(X) 上的信念分布初始化（候选状态加权）' };\r\n    }\r\n    if (!this._belief) return { ok: false, reason: '未初始化信念态 B（先 B(candidates) 建先验）' };\r\n    const ent = -Object.values(this._belief.dist).reduce((a, p) => a + (p > 0 ? p * Math.log2(p) : 0), 0);\r\n    return { ok: true, belief: this._belief.dist, entropy: +ent.toFixed(4), grounded: false,\r\n      honesty: 'BELIEF-LEVEL: 信念是观测后验，属 conjecture 级，不进入证明链；高熵=高不确定，规划须保守/需更多观测' };\r\n  },\r\n  B_update(obs) {\r\n    if (!this._belief) return { ok: false, reason: '未初始化信念态 B' };\r\n    this._belief.obs.push(obs);\r\n    this._belief.evidence = (this._belief.evidence || 0) + 1; // 观测证据量 +1，供 B_envelope 计算置信度\r\n    if (typeof reconcile === 'function' && obs && typeof obs === 'object' && 'belief' in obs && 'fact' in obs) {\r\n      const r = reconcile(obs.belief, obs.fact);\r\n      if (r && r.mode) this._belief.lastReconcile = r;\r\n    }\r\n    return { ok: true, belief: this._belief.dist, observations: this._belief.obs.length,\r\n      honesty: 'BELIEF-LEVEL: 观测更新后验，仍属 conjecture 级' };\r\n  },\r\n  // —— B_envelope：把加权后验膨胀为 D-S 不精确概率包络 [belief, plausibility]（P0 端到端主线）——\r\n  // 第一性原理（Walley linear-vacuous 混合 / imprecise Dirichlet）：仅\"声明\"的分布若无观测证据支撑，\r\n  // 应是**完全无知**（c=0 ⟹ belief=0, plausibility=1）；证据越多越收窄到精确后验。\r\n  // 置信度 c = E/(E+K)，E=观测证据量，K=先验强度（默认=候选数，即 Laplace 伪计数）。\r\n  // 复用 beliefPlausibility 保证包络 [belief,plausibility] 合法；结果直接喂 decideImprecise 做端到端决策。\r\n  B_envelope(opts) {\r\n    opts = opts || {};\r\n    if (!this._belief) return { ok: false, reason: '未初始化信念态 B（先 B(candidates) 建先验）' };\r\n    const dist = this._belief.dist, keys = Object.keys(dist), n = keys.length;\r\n    const E = (this._belief.evidence || 0);\r\n    const K = (opts.priorStrength == null ? n : +opts.priorStrength);\r\n    const c = E > 0 ? E / (E + K) : 0; // 证据=0 ⟹ 完全无知\r\n    const env = {};\r\n    for (const k of keys) {\r\n      const p = dist[k];\r\n      const bp = beliefPlausibility(c * p, c * p + (1 - c));\r\n      env[k] = { belief: bp.belief, plausibility: bp.plausibility, width: bp.width };\r\n    }\r\n    const widths = keys.map(function (k) { return env[k].width; });\r\n    const maxW = widths.length ? Math.max.apply(null, widths) : 0;\r\n    return { ok: true, envelope: env, confidence: +c.toFixed(4), evidence: E,\r\n      method: 'linear-vacuous 混合（Walley 不精确概率）：c=' + c.toFixed(3) + ' 膨胀后验为 D-S 包络 [belief=c·p, plausibility=c·p+(1−c)]',\r\n      globalIgnoranceWidth: +maxW.toFixed(4), grounding: 'BELIEF-LEVEL',\r\n      honesty: 'BELIEF-LEVEL：包络宽度=不确定性本身；宽度大 ⟹ 决策须保守/需更多观测；decideImprecise 据此判 ACCEPT/REJECT/UNKNOWN' };\r\n  }\r\n};\r\n\r\n// 把 nondeterministic 转移关系 candidates 同时挂到 f 上：API 形态 f 单点函数 ↔ f.candidates 非确定关系\r\n// （V_robust 内部 this.f.candidates、测试 BT.f.candidates 均依赖此）。bind(BrainTuple) 保证 this._learned 正确解析。\r\nBrainTuple.f.candidates = BrainTuple.candidates.bind(BrainTuple);\r\n\r\n// ── 八元组 𝔹 接入 LCF 证明链（把落地的 h/U/V/M 钉成可审计定理）──\r\nMathKernel.axiom('AX_TUPLE_FORMAL',\r\n  '世界通用大脑存在唯一可约的数学形态 𝔹=(X,h,b,f,U,V,Inv,M)：状态空间 X、观测通道 h、物理身体 b、动力学 f、执行通道 U、价值 V、不变量 Inv、他心 M；部分可观测下增补信念态 B（Δ(X) 上的分布）作为第九元扩展',\r\n  { field: '形态学/系统论', source: 'docs/TUPLE-REEXAMINATION.md 不可约性推导 + docs/FIRST-PRINCIPLES-REEXAMINATION.md 完善', informal: '八元组是大脑的数学骨架，由四个建模目标 + 不可逆伤害的不可约性导出；B 为部分可观测扩展，属 belief-level' });\r\nMathKernel.theorem('THM_OBS_CHANNEL_RANGE',\r\n  '观测通道 h: X→O 的值域由身体传感器集张成；未声明观测契约时 h 诚实退化（返回 ok:false），不编造观测',\r\n  { by: 'COMPUTE', from: ['AX_TUPLE_FORMAL'], field: '观测理论',\r\n    proof: 'h 实现逐传感器投影（getBody().observation.sensors → O）；无传感器则值域空，诚实返回未定义',\r\n    evidence: 'verify() 实跑 BrainTuple.h 不抛且返回结构合法',\r\n    check: function () { try { const r = BrainTuple.h({}); return !!(r && typeof r === 'object'); } catch (e) { return false; } } });\r\nMathKernel.theorem('THM_ACTION_SAFE_CLOSED',\r\n  '执行通道 U 中每个动作都已通过 checkHard 双层安全门（+IRREVERSIBLE 显式授权）；U 中任意动作下发前不变量不被破坏',\r\n  { by: 'DERIVE', from: ['AX_TUPLE_FORMAL', 'THM_CBF_INVARIANCE'], field: '执行安全',\r\n    proof: 'U 由 getBody().caps 经 checkHard 过滤构造（见 BrainTuple.U），与 execute() 四道 fail-closed 守卫（checkHard 双层 / IRREVERSIBLE-HALT / OBSERVATION-BLIND-SPOT / pre 重校验）同源',\r\n    evidence: 'BrainTuple.U 与 execute 共用 checkHard / IRREVERSIBLE-HALT，证明链一致' });\r\nMathKernel.theorem('THM_VALUE_ITER_CONVERGE',\r\n  '到达价值 V: X→[0,1] 由值迭代（固定点）给出，在有限节点图上 ≤|X| 步收敛到最优到达概率',\r\n  { by: 'DERIVE', from: ['AX_TUPLE_FORMAL', 'THM_BANACH_FP', 'THM_WEIERSTRASS'], field: '动态规划',\r\n    proof: '值迭代是度量空间压缩映射（THM_BANACH_FP）的离散形式；极值定理（THM_WEIERSTRASS）保证最优到达值存在',\r\n    evidence: 'BrainTuple.V 实跑值迭代返回固定点 V 表' });\r\nMathKernel.theorem('THM_OTHER_MIND_BELIEF',\r\n  '他心 M 建模为对其他 agent 的**信念状态**（belief-level）：registerAgent / observeAgent / beliefAbout 构造可审计信念结构，诚实标注真实性不可判定',\r\n  { by: 'DERIVE', from: ['AX_TUPLE_FORMAL', 'AX_PROB'], field: '心智理论',\r\n    proof: '信念 = 观测历史的后验（AX_PROB）；但\"他心是否真实存在/与我同构\"超出可计算判定（中文房间/他心问题）',\r\n    evidence: 'BrainTuple.M 提供 registerAgent/observeAgent/beliefAbout/deceptionBound 可审计接口' });\r\nMathKernel.theorem('THM_NESTED_BELIEF_KD45',\r\n  '他心 M 的信念算子满足 KD45（K 分配律 / D 一致性 / 4 正内省 / 5 负内省）：嵌套信念 B_i(B_j(…(B_k(p))…)) 可建模且不自相矛盾；checkKd45 机验 D 一致性',\r\n  { by: 'COMPUTE', from: ['AX_TUPLE_FORMAL', 'AX_PROB', 'THM_OTHER_MIND_BELIEF'], field: '心智理论/模态逻辑',\r\n    proof: 'assertNested 存嵌套信念公式 B_i(B_j(…))；nestedBelief 诚实查询（未知返回 UNKNOWN，不编造）；checkKd45 扫描观察者算子 B_i 下是否同时持有 p 与 ¬p 以机验 D 一致性；K/4/5 为信念算子建模契约（BELIEF-LEVEL 假设，非机器证明）',\r\n    evidence: 'BrainTuple.M.assertNested / nestedBelief / checkKd45 实跑：存嵌套信念、查 UNKNOWN、D 一致性可机验',\r\n    check: function () { try { const r = BrainTuple.M.checkKd45('SELF'); return !!(r && typeof r === 'object'); } catch (e) { return false; } } });\r\nMathKernel.conjecture('CONJ_OTHER_MIND_REALITY',\r\n  '他心（其他智能体的真实心智）是否可判定/可读取 —— 哲学与计算双重未决；本内核仅建模信念级 M，不声称读取真实心智',\r\n  { field: '心智哲学', evidence: '诚实边界：任何\"已证明他心\"的断言都是幻觉，故列为猜想并禁止进入证明链（铁律③）' });\r\nMathKernel.theorem('THM_DYNAMICS_LAYERED',\r\n  '动力学 f 分级诚实：图边/具身预测属 KERNEL（确定性）；学习的 f（learnWorldModel 拟合）属 PERCEPTION（mayHallucinate），禁止进入 KERNEL/PROOF 证明链；二者皆无则诚实返回 𝕌',\r\n  { by: 'COMPUTE', from: ['AX_TUPLE_FORMAL', 'AX_PROB'], field: '动力学/学习',\r\n    proof: 'BrainTuple.f 三分支：graph-edge/具身→GROUNDING.KERNEL；learned→GROUNDING.PERCEPTION(mayHallucinate,usableInProof:false)；无→𝕌',\r\n    evidence: 'BrainTuple.f 实跑：注入 learned 模型后返回 kind:\"learned\" 且 grounding=PERCEPTION',\r\n    check: function () { try { const r = BrainTuple.f('NO_SUCH', 'NO_SUCH'); return !!(r && (r.kind === 'unknown' || r.kind === 'learned' || r.kind === 'graph-edge')); } catch (e) { return false; } } });\r\nMathKernel.theorem('THM_BELIEF_LEVEL',\r\n  '信念态 B 建模为 Δ(X) 上的分布（候选状态加权）；部分可观测下大脑维持信念而非单点估计，属 BELIEF-LEVEL/conjecture 级，禁止进入证明链',\r\n  { by: 'COMPUTE', from: ['AX_TUPLE_FORMAL', 'AX_PROB'], field: '部分可观测/滤波',\r\n    proof: 'BrainTuple.B(candidates) 初始化 Δ(X) 加权分布；B_update 用观测刷新后验；熵度量不确定性',\r\n    evidence: 'BrainTuple.B 实跑：初始化返回 dist 且熵可算',\r\n    check: function () { try { const r = BrainTuple.B([{ key: 'a', weight: 1 }, { key: 'b', weight: 1 }]); return !!(r && r.ok && r.belief && r.belief.a >= 0); } catch (e) { return false; } } });\r\nMathKernel.theorem('THM_AUTONOMY_GATE',\r\n  '灵脑执行分级安全：IRREVERSIBLE-HALT 与 SAFE-STOP 为最高优先 fail-closed 闸（不受自主等级影响）；分级人机协同仅在 opts 显式启用时按动作风险等级触发 HUMAN-IN-THE-LOOP',\r\n  { by: 'DERIVE', from: ['AX_TUPLE_FORMAL', 'THM_CBF_INVARIANCE'], field: '执行安全',\r\n    proof: 'AUTONOMY.riskTierOf 给每动作风险等级；启用分级时 riskTier>asl 且未授权即停机；不可逆闸先于分级闸（execute 中 IRREVERSIBLE-HALT 段位于分级段之前）',\r\n    evidence: 'execute() 四道 fail-closed 守卫 + AUTONOMY 分级段同源 checkHard' });\r\nMathKernel.conjecture('CONJ_LEARNED_F_SOUND',\r\n  '学习的 f（线性 SEM lite）在分布外/非线性域的预测保真性 —— 未证明（lite 等价，非真实世界模型）；列为猜想，禁止进入证明链',\r\n  { field: '世界模型', evidence: '诚实边界：学习的 f 仅 PERCEPTION 级探索用，不得作为证明前提（铁律③）' });\r\nMathKernel.theorem('THM_UNCERTAINTY_PROPAGATED',\r\n  '不确定性作为一等公民端到端传播：f 非确定候选(f.candidates) → B 不精确包络(B_envelope，linear-vacuous 混合) → V 稳健可达包络(V_robust，区间MDP) → execute 据包络决策(decideImprecise)；确定性内核不被概率分量污染（铁律③+grounding 分层）',\r\n  { by: 'COMPUTE', from: ['AX_TUPLE_FORMAL', 'AX_PROB', 'THM_DYNAMICS_LAYERED', 'THM_BELIEF_LEVEL'], field: '不确定性传播',\r\n    proof: 'f.candidates 返回候选集并标 nondeterministic；B_envelope 用 beliefPlausibility 膨胀为 D-S 包络；V_robust 悲观/乐观值迭代给 [low,high]；execute(useImprecise) 调 decideImprecise 在风险带停机',\r\n    evidence: 'f.candidates / B_envelope / V_robust / execute(useImprecise) 实跑可验证' });\r\nMathKernel.theorem('THM_ROBUST_REACH',\r\n  'V_robust 给出区间 MDP 稳健可达包络 [V_low,V_high]：分类 (1,1) 稳健可达 / (0,1) 风险可达（仅赖 PERCEPTION 转移）/ (0,0) 不可达；规划据分类保守决策',\r\n  { by: 'COMPUTE', from: ['AX_TUPLE_FORMAL', 'THM_BANACH_FP'], field: '稳健可达性',\r\n    proof: 'V_robust 悲观仅 KERNEL 图边推进、乐观含 PERCEPTION 学习f 预测，两次值迭代（压缩映射，THM_BANACH_FP）给包络',\r\n    evidence: 'V_robust 实跑返回 envelope + classification' });\r\n\r\n// 八元组能力追溯：把落地能力映射回支撑定理\r\nCAPABILITY_THEOREMS.tuple = ['THM_OBS_CHANNEL_RANGE', 'THM_ACTION_SAFE_CLOSED', 'THM_VALUE_ITER_CONVERGE', 'THM_OTHER_MIND_BELIEF', 'THM_DYNAMICS_LAYERED', 'THM_BELIEF_LEVEL', 'THM_AUTONOMY_GATE', 'THM_UNCERTAINTY_PROPAGATED', 'THM_ROBUST_REACH'];\r\nCAPABILITY_THEOREMS.observation = ['THM_OBS_CHANNEL_RANGE', 'THM_BUCKINGHAM_PI'];\r\nCAPABILITY_THEOREMS['action-space'] = ['THM_ACTION_SAFE_CLOSED'];\r\nCAPABILITY_THEOREMS.value = ['THM_VALUE_ITER_CONVERGE', 'THM_ROBUST_REACH'];\r\nCAPABILITY_THEOREMS['other-mind'] = ['THM_OTHER_MIND_BELIEF', 'THM_NESTED_BELIEF_KD45'];\r\nCAPABILITY_THEOREMS.uncertainty = ['THM_UNCERTAINTY_PROPAGATED', 'THM_ROBUST_REACH'];\r\n\r\n// ══ 架构不变量·证明账本机检（启动自检，断裂则内核拒绝启动）══\r\n// 使「可审计」从注释君子协定变物理铁律：能力映射闭合 + 推导链闭合，否则 kernel 不应跑。\r\n(function bootVerifyLedger() {\r\n  var _led = MathKernel.verifyLedger();\r\n  MathKernel.ledger = _led;\r\n  if (!_led.ok) {\r\n    throw new Error('PROOF_LEDGER_BROKEN: ' + JSON.stringify({ theoremsInvalid: _led.theoremsInvalid, capBroken: _led.capabilityBroken }));\r\n  }\r\n})();\r\n\r\n// ══ 架构不变量·信任防火墙机检（启动自检，守卫须真能拦截 PERCEPTION）══\r\n(function bootFirewall() {\r\n  var threw = false;\r\n  try { FIREWALL.assert({ mayHallucinate: true }, 'boot-perception-test'); } catch (e) { threw = true; }\r\n  if (!threw) throw new Error('FIREWALL_BROKEN: 守卫未能拦截 PERCEPTION 值（脊柱失效）');\r\n  FIREWALL.assert({ kind: 'graph-edge' }, 'boot-kernel-test'); // KERNEL 值须放行（不抛）\r\n  MathKernel.firewall = { ok: true, verdict: '信任防火墙激活：PERCEPTION 值类型级拒绝直连 KERNEL/PROOF；唯一合法通道 = liftToBelief(D-S 包络)' };\r\n})();\r\n\r\n// ══ 架构不变量·八元组 typed state（决策只读、学习只写候选池；BrainTuple 为形态学载体）══\r\n(function bootEightTuple() {\r\n  if (typeof BrainTuple !== 'undefined') {\r\n    MathKernel.state = BrainTuple;\r\n    MathKernel.eightTuple = function () { return BrainTuple; };\r\n  }\r\n})();\r\n\r\n// ══ 架构不变量·数学思想索引（可发现性；LingNaoThinking）══\r\nMathKernel.thinking = LingNaoThinking;\r\n\r";
